      "reading": "Spiele h–d–f–a einmal in a-Moll und einmal in C-Dur. Welche Bassstufe hat der Akkord jeweils? Vergleiche nun, was der Melodieton unmittelbar vor der Septime und der Bass nach dem Akkord tun.",
      "comparisons": [],
